SystemRoutineControllerAsyncWaiter::SystemRoutineControllerAsyncWaiter(
    SystemRoutineController* proxy) : proxy_(proxy) {}

SystemRoutineControllerAsyncWaiter::~SystemRoutineControllerAsyncWaiter() = default;

void SystemRoutineControllerAsyncWaiter::GetSupportedRoutines(
    std::vector<RoutineType>* out_routines) {
  base::RunLoop loop;
  proxy_->GetSupportedRoutines(
      base::BindOnce(
          [](base::RunLoop* loop,
             std::vector<RoutineType>* out_routines
,
             const std::vector<RoutineType>& routines) {*out_routines = std::move(routines);
            loop->Quit();
          },
          &loop,
          out_routines));
  loop.Run();
}

std::vector<RoutineType> SystemRoutineControllerAsyncWaiter::GetSupportedRoutines(
    ) {
  std::vector<RoutineType> async_wait_result;
  GetSupportedRoutines(&async_wait_result);
  return async_wait_result;
}






